{
  "table": "sensor_readings",
  "columns": [
    {
      "target": "device_id",
      "source": [
        "Sensor ID"
      ],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 1.0,
      "note": "Maps directly to device_id and is already uppercase"
    },
    {
      "target": "read_at",
      "source": [
        "Recorded At"
      ],
      "transform": "datetime",
      "params": {
        "format": "%Y-%m-%dT%H:%M:%SZ"
      },
      "confidence": 1.0,
      "note": "Timestamp in UTC matching expected format"
    },
    {
      "target": "temperature_c",
      "source": [
        "Temp (C)"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Temperature in Celsius, updated from Fahrenheit source in previous layout"
    },
    {
      "target": "humidity_pct",
      "source": [
        "Humidity (%)"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Relative humidity percentage"
    },
    {
      "target": "battery_v",
      "source": [
        "Battery (V)"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Battery voltage"
    }
  ],
  "ignore": {},
  "review": [
    "Source column 'Temp (F)' was renamed to 'Temp (C)' and unit changed from Fahrenheit to Celsius."
  ],
  "author": "model"
}
